#include <stdio.h>

int main(void) {
    int bus = 42;
    int *p = &bus;
    int **pp = &p;

    printf("bus   = %d\n", bus);
    printf("*p    = %d\n", *p);
    printf("**pp  = %d\n", **pp);

    **pp = 50;
    printf("After **pp = 50, bus = %d\n", bus);

    int *q = NULL;
    if (q == NULL) {
        printf("q points nowhere, so we do not touch it.\n");
    }
    return 0;
}

#include <stdio.h>

void point_to_bigger(int **slot, int *a, int *b) {
    if (*a > *b) {
        *slot = a;
    } else {
        *slot = b;
    }
}

int main(void) {
    int x = 12, y = 30;
    int *big = NULL;
    point_to_bigger(&big, &x, &y);
    if (big != NULL) {
        printf("Bigger value: %d\n", *big);
    }
    return 0;
}
